import React, { useState, useRef, useEffect } from 'react';
import { deptAPI } from '../utils/api';

export default function LoginQRModal({ onLoginSuccess, onClose }) {
  const [tab, setTab] = useState('camera'); // camera or manual
  const [deptId, setDeptId] = useState('');
  const [error, setError] = useState('');
  const [result, setResult] = useState(null);
  const [stream, setStream] = useState(null);
  const videoRef = useRef();
  const canvasRef = useRef();

  useEffect(() => {
    if (tab === 'camera') {
      startCamera();
    } else {
      stopCamera();
    }
    return () => stopCamera();
  }, [tab]);

  const startCamera = async () => {
    try {
      const s = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment' } 
      });
      setStream(s);
      if (videoRef.current) videoRef.current.srcObject = s;
      scanForCode();
    } catch {
      setError('Camera not available. Use manual entry instead.');
      setTab('manual');
    }
  };

  const stopCamera = () => {
    if (stream) stream.getTracks().forEach(t => t.stop());
    setStream(null);
  };

  const scanForCode = () => {
    if (!videoRef.current) return;
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    const video = videoRef.current;

    const scan = () => {
      if (video.readyState === video.HAVE_ENOUGH_DATA) {
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        ctx.drawImage(video, 0, 0);
      }
      if (stream) requestAnimationFrame(scan);
    };
    scan();
  };

  const lookup = async (e) => {
    if (e) e.preventDefault();
    if (!deptId) return;
    setError(''); 
    setResult(null);
    try {
      const r = await deptAPI.list();
      const dept = r.data.departments.find(d => String(d.id) === String(deptId));
      if (dept) {
        setResult(dept);
        stopCamera();
      } else {
        setError('Department not found.');
      }
    } catch (err) {
      setError(err.response?.data?.error || 'Invalid QR code.');
    }
  };

  const handleLogin = () => {
    if (result) {
      onLoginSuccess(result.id, result.name);
      onClose();
    }
  };

  return (
    <div className="overlay" onClick={e => e.target === e.currentTarget && onClose()}>
      <div className="modal">
        <div className="modal-head">
          <span className="modal-title">📷 Scan Department QR</span>
          <button className="btn btn-outline btn-sm" onClick={onClose}>✕</button>
        </div>
        <div className="modal-body">
          <div style={{ display: 'flex', gap: 8, marginBottom: 16, borderBottom: '1px solid var(--border)' }}>
            <button 
              className={`btn btn-sm ${tab === 'camera' ? 'btn-navy' : 'btn-outline'}`}
              onClick={() => setTab('camera')}
              style={{ borderBottom: tab === 'camera' ? '3px solid var(--navy)' : 'none' }}
            >
              📷 Camera
            </button>
            <button 
              className={`btn btn-sm ${tab === 'manual' ? 'btn-navy' : 'btn-outline'}`}
              onClick={() => setTab('manual')}
              style={{ borderBottom: tab === 'manual' ? '3px solid var(--navy)' : 'none' }}
            >
              ✏️ Manual
            </button>
          </div>

          {error && <div className="alert a-err">{error}</div>}

          {tab === 'camera' && (
            <div style={{ marginBottom: 16 }}>
              <video 
                ref={videoRef} 
                style={{ 
                  width: '100%', 
                  borderRadius: 8, 
                  backgroundColor: '#000',
                  maxHeight: 300
                }} 
                autoPlay 
                playsInline
              />
              <canvas ref={canvasRef} style={{ display: 'none' }} />
              <p style={{ fontSize: 12, color: 'var(--t2)', marginTop: 8, textAlign: 'center' }}>
                Point camera at department QR code
              </p>
            </div>
          )}

          {tab === 'manual' && (
            <form onSubmit={lookup} style={{ display:'flex', gap:8, marginBottom: 16 }}>
              <input 
                className="inp" 
                type="text" 
                placeholder="Enter Department ID"
                value={deptId} 
                onChange={e => setDeptId(e.target.value)} 
                required 
              />
              <button type="submit" className="btn btn-navy" style={{ whiteSpace:'nowrap' }}>
                Look Up
              </button>
            </form>
          )}

          {result && (
            <div className="card mt4">
              <div className="card-body">
                <div className="alert a-ok mb2">✅ Department found!</div>
                <table style={{ width:'100%' }}>
                  <tbody>
                    <tr style={{ borderBottom:'1px solid var(--border)' }}>
                      <td style={{ padding:'8px 0', fontWeight:600, fontSize:11, color:'var(--t2)', width:70, textTransform:'uppercase' }}>Department</td>
                      <td style={{ padding:'8px 0' }}>{result.name}</td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
        <div className="modal-foot">
          {result ? (
            <>
              <button className="btn btn-navy" onClick={handleLogin} style={{ flex: 1 }}>Login to {result.name}</button>
              <button className="btn btn-outline" onClick={onClose}>Cancel</button>
            </>
          ) : (
            <button className="btn btn-outline" onClick={onClose}>Close</button>
          )}
        </div>
      </div>
    </div>
  );
}
